<head>
<meta charset="UTF-8">
<title>Diario Official — 1 de Abril de 1930</title>
<style>
    body {
        background: #ffffff;
        color: #111;
        font-family: "Times New Roman", Times, serif;
        font-size: 13px;
        line-height: 1.15;
        margin: 20px 40px;
        text-align: justify;
    }
    .cabecalho {
        display: flex;
        justify-content: space-between;
        align-items: flex-end;
        font-weight: bold;
        letter-spacing: 1px;
        padding-bottom: 2px;
    }
    .cabecalho .esq { font-size: 14px; }
    .cabecalho .centro { font-size: 16px; letter-spacing: 2px; }
    .cabecalho .dir { font-size: 14px; }
    hr.dupla {
        border: none;
        border-top: 2px solid #000;
        border-bottom: 1px solid #000;
        height: 2px;
        margin: 2px 0 8px 0;
    }
    .colunas {
        column-count: 3;
        column-gap: 22px;
        column-rule: 1px solid #000;
    }
    p {
        margin: 0;
        text-indent: 1.2em;
    }
    p.semrecuo { text-indent: 0; }
    h2, h3, h4, h5 {
        margin: 8px 0 4px 0;
        text-align: center;
        font-weight: normal;
    }
    h2.titulo-grande {
        font-size: 20px;
        letter-spacing: 3px;
        margin: 14px 0 8px 0;
    }
    h3.secao {
        font-size: 14px;
        letter-spacing: 2px;
    }
    h4.sub {
        font-size: 13px;
        letter-spacing: 1px;
    }
    h5.sub2 {
        font-size: 13px;
        font-style: normal;
    }
    .italico { font-style: italic; }
    .negrito { font-weight: bold; }
    table.resumo {
        width: 100%;
        border-collapse: collapse;
        font-size: 13px;
    }
    table.resumo td { padding: 0; vertical-align: bottom; }
    table.resumo td.num { text-align: right; }
    .separador {
        text-align: center;
        margin: 10px 0;
    }
    .separador::before {
        content: "———————";
        letter-spacing: 2px;
    }
    .recuo-lista {
        text-indent: 0;
        padding-left: 1.4em;
        text-align: center;
    }
</style>
